-- KOSPI 939개 종목의 별칭(stock_alias 686건)과 테마(stock_theme 1019건) 적재.
-- 전제: V1~V7에서 stock_info(stock_code)에 대상 종목이 이미 등록되어 있어야 함.
-- 현재 V3 테이블 구조에 맞춰 stock_code를 직접 저장함.
-- alias_type: NICKNAME(줄임말) / HANGUL(영문 이니셜의 한글 표기) / PREFERRED(우선주 표기) / GROUP(그룹사)
-- theme_type: INDUSTRY(KRX 표준 업종, 종목당 1건) / MARKET(시장 테마)

-- V3 테이블에 별칭/테마 유형 컬럼 추가
ALTER TABLE stock_alias
    ADD COLUMN alias_type VARCHAR(20) NOT NULL DEFAULT 'NICKNAME'
    COMMENT '별칭 유형: NICKNAME / HANGUL / PREFERRED / GROUP';

ALTER TABLE stock_theme
    ADD COLUMN theme_type VARCHAR(20) NOT NULL DEFAULT 'MARKET'
    COMMENT '테마 유형: INDUSTRY / MARKET';

-- ===== stock_alias =====

-- ===== stock_theme =====

